$(document).ready(function() {
var ticking = false;
window.addEventListener('scroll', function() {
if (!ticking) {
window.requestAnimationFrame(function() {
var nav = document.querySelector('.navbar-custom');
if (nav) {
if (window.scrollY > 50) {
nav.classList.add('scrolled');
} else {
nav.classList.remove('scrolled');
}
}
ticking = false;
});
ticking = true;
}
}, { passive: true });
setTimeout(function() {
$('.alert-dismissible').fadeOut('slow', function() {
$(this).remove();
});
}, 5000);
if (typeof bootstrap !== 'undefined' && bootstrap.Tooltip) {
var tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));
tooltipTriggerList.map(function (tooltipTriggerEl) {
return new bootstrap.Tooltip(tooltipTriggerEl);
});
}
if (typeof GLightbox !== 'undefined' && document.querySelector('.glightbox')) {
const lightbox = GLightbox({
selector: '.glightbox',
touchNavigation: true,
loop: true,
autoplayVideos: true,
zoomable: true
});
}
function filterGallery(filter, label) {
var icon = (filter === 'all') ? 'fa-images' : 'fa-mountain';
$('#gallery_active_title').html('<i class="fas ' + icon + ' me-2"></i>' + label);
if (filter === 'all') {
$('.gallery-col').fadeIn(300);
$('#gallery_no_results').hide();
$('#gallery_visible_count').text($('.gallery-col').length + ' photos');
} else {
$('.gallery-col').hide();
var matched = $('.gallery-col[data-category="' + filter + '"]');
matched.fadeIn(300);
$('#gallery_visible_count').text(matched.length + ' photos');
if (matched.length === 0) {
$('#gallery_no_results').fadeIn(200);
} else {
$('#gallery_no_results').hide();
}
}
}
$(document).on('click', '.gallery-sidebar-link', function(e) {
e.preventDefault();
var filter = $(this).attr('data-filter');
var linkText = $(this).find('.gallery-sidebar-text').text().trim();
$('.gallery-sidebar-link').removeClass('active');
$(this).addClass('active');
var matchingOpt = $('.gallery-dropdown-option[data-value="' + filter + '"]');
$('.gallery-dropdown-option').removeClass('active');
matchingOpt.addClass('active');
$('#gallery_dropdown_text').text(linkText);
$('#gallery_dropdown_badge').text(matchingOpt.find('.gallery-dropdown-opt-count').text());
filterGallery(filter, linkText);
});
$(document).on('click', '#gallery_dropdown_trigger', function(e) {
e.stopPropagation();
$('#gallery_custom_dropdown').toggleClass('open');
});
$(document).on('click', '.gallery-dropdown-option', function() {
var filter = $(this).attr('data-value');
var label = $(this).find('.gallery-dropdown-opt-text').text().trim();
var count = $(this).find('.gallery-dropdown-opt-count').text().trim();
$('.gallery-dropdown-option').removeClass('active');
$(this).addClass('active');
$('#gallery_dropdown_text').text(label);
$('#gallery_dropdown_badge').text(count);
$('#gallery_custom_dropdown').removeClass('open');
$('.gallery-sidebar-link').removeClass('active');
$('.gallery-sidebar-link[data-filter="' + filter + '"]').addClass('active');
filterGallery(filter, label);
});
$(document).on('click', function(e) {
if (!$(e.target).closest('#gallery_custom_dropdown').length) {
$('#gallery_custom_dropdown').removeClass('open');
}
});
$('.offcanvas-body .nav-link:not(.dropdown-toggle)').on('click', function() {
var offcanvasEl = document.getElementById('mainNavbarOffcanvas');
if (offcanvasEl && typeof bootstrap !== 'undefined' && bootstrap.Offcanvas) {
var instance = bootstrap.Offcanvas.getInstance(offcanvasEl);
if (instance) {
instance.hide();
}
}
});
$('.offcanvas-body .dropdown-item').on('click', function() {
var offcanvasEl = document.getElementById('mainNavbarOffcanvas');
if (offcanvasEl && typeof bootstrap !== 'undefined' && bootstrap.Offcanvas) {
var instance = bootstrap.Offcanvas.getInstance(offcanvasEl);
if (instance) {
setTimeout(function() { instance.hide(); }, 150);
}
}
});
var offcanvasEl = document.getElementById('mainNavbarOffcanvas');
if (offcanvasEl) {
offcanvasEl.addEventListener('show.bs.offcanvas', function() {
$('body').addClass('offcanvas-open');
});
offcanvasEl.addEventListener('hidden.bs.offcanvas', function() {
$('body').removeClass('offcanvas-open');
});
}
$('table.table').each(function() {
var $table = $(this);
var headers = [];
$table.find('thead th').each(function() {
headers.push($(this).text().trim());
});
$table.find('tbody tr').each(function() {
$(this).find('td').each(function(index) {
if (headers[index]) {
$(this).attr('data-label', headers[index]);
}
});
});
});
(function initGalleryLightbox() {
if ($('.gallery-grid-item').length === 0) return;
if ($('#galleryLightbox').length === 0) {
$('body').append(
'<div class="gallery-lightbox-overlay" id="galleryLightbox">' +
'<span class="gallery-lightbox-close" id="lightboxClose"><i class="fas fa-times"></i></span>' +
'<button class="gallery-lightbox-nav prev" id="lightboxPrev" type="button" aria-label="Previous"><i class="fas fa-chevron-left"></i></button>' +
'<button class="gallery-lightbox-nav next" id="lightboxNext" type="button" aria-label="Next"><i class="fas fa-chevron-right"></i></button>' +
'<div class="gallery-lightbox-content">' +
'<img src="" alt="Gallery Image" id="lightboxImg">' +
'<div class="gallery-lightbox-info" id="lightboxInfo">' +
'<h5 id="lightboxCaption"></h5>' +
'<span id="lightboxTrek"></span>' +
'</div>' +
'</div>' +
'</div>'
);
}
var currentIdx = 0;
function getVisibleItems() {
return $('.gallery-grid-item:visible');
}
function showLightboxAtIndex(index) {
var $items = getVisibleItems();
if ($items.length === 0) return;
if (index < 0) index = $items.length - 1;
if (index >= $items.length) index = 0;
currentIdx = index;
var $target = $items.eq(currentIdx);
var $img = $target.find('img');
var imgSrc = $img.attr('src');
var imgAlt = $img.attr('alt') || 'Gallery Image';
var caption = $target.find('h5').text().trim();
var trekName = $target.find('.gallery-item-trek').text().trim();
$('#lightboxImg').attr('src', imgSrc).attr('alt', imgAlt);
if (caption) {
$('#lightboxCaption').text(caption).show();
} else {
$('#lightboxCaption').hide();
}
if (trekName) {
$('#lightboxTrek').html('<i class="fas fa-mountain me-1"></i>' + trekName).show();
} else {
$('#lightboxTrek').hide();
}
$('#galleryLightbox').addClass('active');
$('body').css('overflow', 'hidden');
}
$(document).on('click', '.gallery-grid-item', function(e) {
e.preventDefault();
var $items = getVisibleItems();
var index = $items.index(this);
if (index !== -1) {
showLightboxAtIndex(index);
}
});
$(document).on('click', '#galleryLightbox, #lightboxClose', function(e) {
if (e.target === this || $(e.target).closest('#lightboxClose').length) {
$('#galleryLightbox').removeClass('active');
$('body').css('overflow', '');
}
});
$(document).on('click', '#lightboxPrev', function(e) {
e.stopPropagation();
showLightboxAtIndex(currentIdx - 1);
});
$(document).on('click', '#lightboxNext', function(e) {
e.stopPropagation();
showLightboxAtIndex(currentIdx + 1);
});
$(document).on('keydown', function(e) {
if ($('#galleryLightbox').hasClass('active')) {
if (e.key === 'Escape') {
$('#galleryLightbox').removeClass('active');
$('body').css('overflow', '');
} else if (e.key === 'ArrowLeft') {
showLightboxAtIndex(currentIdx - 1);
} else if (e.key === 'ArrowRight') {
showLightboxAtIndex(currentIdx + 1);
}
}
});
var touchStartX = 0;
var touchEndX = 0;
$(document).on('touchstart', '#galleryLightbox', function(e) {
touchStartX = e.originalEvent.changedTouches[0].screenX;
});
$(document).on('touchend', '#galleryLightbox', function(e) {
touchEndX = e.originalEvent.changedTouches[0].screenX;
var diff = touchStartX - touchEndX;
if (Math.abs(diff) > 40) {
if (diff > 0) {
showLightboxAtIndex(currentIdx + 1);
} else {
showLightboxAtIndex(currentIdx - 1);
}
}
});
})();
(function initLazyLoading() {
if ('IntersectionObserver' in window) {
var lazyImages = document.querySelectorAll('img[loading="lazy"]');
var imageObserver = new IntersectionObserver(function(entries) {
entries.forEach(function(entry) {
if (entry.isIntersecting) {
var img = entry.target;
if (img.dataset.src) {
img.src = img.dataset.src;
img.removeAttribute('data-src');
}
img.classList.add('loaded');
imageObserver.unobserve(img);
}
});
}, {
rootMargin: '100px 0px',
threshold: 0.01
});
lazyImages.forEach(function(img) {
imageObserver.observe(img);
});
} else {
document.querySelectorAll('img[loading="lazy"]').forEach(function(img) {
if (img.dataset.src) {
img.src = img.dataset.src;
}
img.classList.add('loaded');
});
}
})();
(function initValidationScroll() {
$('form').on('submit', function() {
var $form = $(this);
var firstInvalid = $form.find(':invalid').first();
if (firstInvalid.length > 0) {
$('html, body').stop().animate({
scrollTop: firstInvalid.offset().top - 120
}, 400);
firstInvalid.focus();
}
});
})();
(function initMobileBottomCta() {
if ($('.mobile-bottom-cta').length > 0) {
$('body').addClass('has-bottom-cta');
$('#mobile-book-btn').on('click', function(e) {
e.preventDefault();
var target = $('#booking-form-anchor');
if (target.length > 0) {
$('html, body').animate({
scrollTop: target.offset().top - 80
}, 600);
}
});
}
})();
(function initBlogCarousel() {
const container = document.getElementById('blog-carousel-container');
const prevBtn = document.getElementById('blog-carousel-prev');
const nextBtn = document.getElementById('blog-carousel-next');
if (!container) return;
const getScrollAmount = () => {
const firstCard = container.querySelector('.blog-carousel-card');
if (firstCard) {
return firstCard.clientWidth + 24;
}
return container.clientWidth * 0.75;
};
if (prevBtn && nextBtn) {
prevBtn.addEventListener('click', function() {
container.scrollBy({
left: -getScrollAmount(),
behavior: 'smooth'
});
});
nextBtn.addEventListener('click', function() {
container.scrollBy({
left: getScrollAmount(),
behavior: 'smooth'
});
});
const updateArrows = () => {
requestAnimationFrame(() => {
const scrollLeft = container.scrollLeft;
const maxScrollLeft = container.scrollWidth - container.clientWidth;
if (scrollLeft <= 5) {
prevBtn.style.opacity = '0.4';
prevBtn.style.pointerEvents = 'none';
} else {
prevBtn.style.opacity = '1';
prevBtn.style.pointerEvents = 'auto';
}
if (scrollLeft >= maxScrollLeft - 5) {
nextBtn.style.opacity = '0.4';
nextBtn.style.pointerEvents = 'none';
} else {
nextBtn.style.opacity = '1';
nextBtn.style.pointerEvents = 'auto';
}
});
};
container.addEventListener('scroll', updateArrows);
window.addEventListener('resize', updateArrows);
setTimeout(updateArrows, 150);
}
let isDown = false;
let startX;
let scrollLeft;
let isMoving = false;
container.addEventListener('mousedown', function(e) {
if (e.button !== 0) return;
isDown = true;
isMoving = false;
container.classList.add('active-dragging');
startX = e.pageX - container.offsetLeft;
scrollLeft = container.scrollLeft;
});
container.addEventListener('mouseleave', function() {
if (isDown) {
isDown = false;
container.classList.remove('active-dragging');
}
});
container.addEventListener('mouseup', function(e) {
if (isDown) {
isDown = false;
container.classList.remove('active-dragging');
if (isMoving) {
const preventClick = function(clickEvent) {
clickEvent.preventDefault();
clickEvent.stopPropagation();
container.removeEventListener('click', preventClick, true);
};
container.addEventListener('click', preventClick, true);
}
}
});
container.addEventListener('mousemove', function(e) {
if (!isDown) return;
const x = e.pageX - container.offsetLeft;
const walk = (x - startX) * 1.5;
if (Math.abs(walk) > 3) {
isMoving = true;
}
e.preventDefault();
container.scrollLeft = scrollLeft - walk;
});
})();
(function initHeroAutocomplete() {
const $searchInput = $('#hero-search-input');
const $resultsContainer = $('#autocomplete-results');
if ($searchInput.length === 0 || $resultsContainer.length === 0) return;
const baseUrl = $searchInput.attr('data-base-url') || '';
let debounceTimer = null;
let selectedIndex = -1;
$searchInput.on('input', function() {
clearTimeout(debounceTimer);
const query = $(this).val().trim();
selectedIndex = -1;
if (query.length < 1) {
$resultsContainer.empty().removeClass('show');
return;
}
debounceTimer = setTimeout(function() {
const url = baseUrl + '/ajax/search_treks.php?q=' + encodeURIComponent(query);
$.ajax({
url: url,
type: 'GET',
dataType: 'json',
success: function(data) {
renderSuggestions(data, query);
},
error: function(xhr, status, error) {
console.error('AJAX Error:', error);
}
});
}, 300);
});
function renderSuggestions(data, query) {
$resultsContainer.empty();
selectedIndex = -1;
if (!data || data.length === 0) {
$resultsContainer.append(
'<div class="dropdown-item-suggestion autocomplete-item no-results">No treks found</div>'
);
$resultsContainer.addClass('show');
return;
}
data.forEach(function(item) {
const redirectUrl = baseUrl + '/treks/' + item.slug;
const titleText = item.title;
const regex = new RegExp('(' + escapeRegExp(query) + ')', 'gi');
const highlightedTitle = titleText.replace(regex, '<strong>$1</strong>');
const suggestionHtml =
'<a href="' + redirectUrl + '" class="dropdown-item-suggestion autocomplete-item" data-slug="' + item.slug + '">' +
'<i class="fas fa-map-marker-alt"></i>' +
'<span>' + highlightedTitle + '</span>' +
'</a>';
$resultsContainer.append(suggestionHtml);
});
$resultsContainer.addClass('show');
}
function escapeRegExp(string) {
return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
$searchInput.on('keydown', function(e) {
const $items = $resultsContainer.find('.autocomplete-item:not(.no-results)');
if ($items.length === 0) return;
if (e.key === 'ArrowDown' || e.keyCode === 40) {
e.preventDefault();
selectedIndex = (selectedIndex + 1) % $items.length;
highlightItem($items);
} else if (e.key === 'ArrowUp' || e.keyCode === 38) {
e.preventDefault();
selectedIndex = (selectedIndex - 1 + $items.length) % $items.length;
highlightItem($items);
} else if (e.key === 'Enter' || e.keyCode === 13) {
if (selectedIndex >= 0 && selectedIndex < $items.length) {
e.preventDefault();
const href = $items.eq(selectedIndex).attr('href');
if (href) {
window.location.href = href;
}
}
} else if (e.key === 'Escape' || e.keyCode === 27) {
$resultsContainer.removeClass('show');
selectedIndex = -1;
}
});
function highlightItem($items) {
$items.removeClass('active');
if (selectedIndex >= 0 && selectedIndex < $items.length) {
const $activeItem = $items.eq(selectedIndex);
$activeItem.addClass('active');
const containerHeight = $resultsContainer.height();
const itemTop = $activeItem.position().top;
const itemHeight = $activeItem.outerHeight();
if (itemTop + itemHeight > containerHeight) {
$resultsContainer.scrollTop($resultsContainer.scrollTop() + itemTop + itemHeight - containerHeight);
} else if (itemTop < 0) {
$resultsContainer.scrollTop($resultsContainer.scrollTop() + itemTop);
}
}
}
$(document).on('click', function(e) {
if (!$(e.target).closest('#hero-search-input, #autocomplete-results').length) {
$resultsContainer.removeClass('show');
selectedIndex = -1;
}
});
$searchInput.on('focus', function() {
const query = $(this).val().trim();
if (query.length >= 1 && $resultsContainer.children().length > 0) {
$resultsContainer.addClass('show');
}
});
})();
$(document).on('click', '.wishlist-btn', function(e) {
var $btn = $(this);
var url = $btn.attr('href');
if (url.indexOf('login.php') !== -1) {
return;
}
e.preventDefault();
if ($btn.data('loading')) return;
$btn.data('loading', true);
$.ajax({
url: url,
type: 'GET',
success: function(response) {
var trekId = $btn.attr('data-trek-id');
var $allSyncBtns = $('.wishlist-btn[data-trek-id="' + trekId + '"]');
if (url.indexOf('action=add') !== -1) {
var newUrl = url.replace('action=add', 'action=remove');
$allSyncBtns.attr('href', newUrl);
$allSyncBtns.addClass('active').attr('title', 'Remove from Wishlist');
$allSyncBtns.find('i').removeClass('far fa-heart').addClass('fas fa-heart');
} else {
var newUrl = url.replace('action=remove', 'action=add');
$allSyncBtns.attr('href', newUrl);
$allSyncBtns.removeClass('active').attr('title', 'Add to Wishlist');
$allSyncBtns.find('i').removeClass('fas fa-heart').addClass('far fa-heart');
}
},
complete: function() {
$btn.data('loading', false);
}
});
});
(function initAnnouncementBar() {
const $slider = $('.announcement-messages-slider');
if ($slider.length === 0) return;
$slider.each(function() {
const $container = $(this);
const $messages = $container.find('.announcement-message');
if ($messages.length <= 1) return;
let currentIndex = 0;
const isSlider = $container.parent().hasClass('announcement-type-slider');
setInterval(function() {
const prevIndex = currentIndex;
currentIndex = (currentIndex + 1) % $messages.length;
const $prevMsg = $messages.eq(prevIndex);
const $nextMsg = $messages.eq(currentIndex);
if (isSlider) {
$messages.removeClass('prev');
$prevMsg.removeClass('active').addClass('prev');
$nextMsg.addClass('active');
} else {
$prevMsg.removeClass('active');
$nextMsg.addClass('active');
}
}, 4000);
});
})();
});